NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Ruth'

CHAPTERS = {
    1: {
        1: 'I den tidi då domarane styrde, vart det uår i landet. Då for ein mann frå Betlehem i Juda i veg med kona si og båe sønerne sine og vilde bu i Moablandet ei stund.',
        2: 'Mannen heitte Elimelek og kona hans No’omi, og dei tvo sønerne Mahlon og Kiljon; dei var efratitar, frå Betlehem i Juda. No kom dei då til Moablandet og vart veranda der.',
        3: 'Og Elimelek, mannen hennar No’omi, døydde; men ho livde att med dei tvo sønerne sine.',
        4: 'Sønerne tok seg konor frå Moablandet; den eine heitte Orpa og den andre Rut. Og dei budde der på lag ti år.',
        5: 'Då døydde både Mahlon og Kiljon, og kvinna livde att etter sønerne sine og mannen sin.',
        6: 'Då budde ho seg til å fara heim att frå Moablandet med sonekonorne sine; for ho hadde høyrt i Moablandet at Herren hadde set um folket sitt og gjeve deim brød.',
        7: 'So gav ho seg i veg frå den staden der ho hadde butt, ho og båe sonekonorne hennar. Då dei var komne eit stykke på vegen heim til Judalandet,',
        8: 'då sagde No’omi til sonekonorne sine: «Snu no og gakk heim att kvar til si mor! Herren vere miskunnsam mot dykk, so som de hev vore mot båe dei avlidne og mot meg!',
        9: 'Herren gjeve at de må finna ro, kvar i huset hjå sin mann!» So kysste ho deim; men dei tok til å gråta,',
        10: 'og sagde til henne: «Nei, me vil fylgja med deg attende til folket ditt.»',
        11: 'Men No’omi svara: «Snu att, døtterne mine; kvifor skulde de ganga med meg? Kann eg endå få søner i mitt liv som kunde verta menner åt dykk?',
        12: 'Snu, døtterne mine, og gakk heim att! for eg er for gamall til å gifta meg att. Og um so var at eg kunde tenkja: «Eg hev endå von,» ja um eg so alt i natt gav meg åt ein mann, og so vart at eg fødde søner,',
        13: 'skulde so de bia til dei vart fullvaksne? skulde so de stengja dykk inne og liva utan menner? Nei, døtterne mine, eg tykkjer synd i dykk, for meg hev Herrens hand råma.»',
        14: 'Då tok dei til å gråta att, og Orpa kysste vermor si til avskil, men Rut vilde ikkje slite seg laus frå henne.',
        15: 'Då sagde ho: Sjå, versyster di hev snutt heim att til folket sitt og til sin gud. Snu no du og, og fylg versyster di!»',
        16: 'Men Rut svara: «Ikkje tel meg til å snu att og ganga frå deg! for der du gjeng, vil eg og ganga, og der du stanar, der vil eg og stana. Ditt folk er mitt folk, og din Gud er min Gud.',
        17: 'Der du døyr, vil eg og døy, og der vil eg verta jorda. Herren late meg bøta for det no og sidan, um noko anna enn dauden skulde skilja meg frå deg!»',
        18: 'Då ho no såg at ho stod fast på sitt og vilde vera med henne, tala ho ikkje meir med henne um dette.',
        19: 'So gjekk dei saman til dei kom til Betlehem. Og då dei kom til Betlehem, kom heile byen i rørsla for deira skuld, og kvinnorne sagde: «Er dette No’omi?»',
        20: 'Men ho sagde til deim: «Kalla meg ikkje No’omi, men kalla meg Mara, for Den Allmegtige hev late mykje sorg koma yver meg.',
        21: 'Rik for eg herifrå, og tomhendt hev Herren late meg koma att. Kvifor kallar de meg No’omi då når Herren hev vitna mot meg, og den Allmegtige hev late det ganga meg so ille?»',
        22: 'So kom då No’omi heim att frå Moabland med sonekona si, moabitkvinna Rut, og dei kom til Betlehem då dei tok til med skurdonni.',
    },
    2: {
        1: 'Det var ein frende åt mannen til No’omi, ein rik mann av ætti hans Elimelek; han heitte Boaz.',
        2: 'Og moabitkvinna Rut sagde til No’omi: «Lat meg ganga ut på åkeren og plukka aks etter einkvan som syner seg venleg mot meg!» Ho svara: «Ja, gjer det, du dotter mi!»',
        3: 'So gjekk ho då av stad og kom til ein åker og plukka aks der etter skurdfolket, og det høvde seg so til at åkerstykket høyrde Boaz til, han som var av ætti hans Elimelek.',
        4: 'Og Boaz kom nett då dit frå Betlehem, og han sagde til skurdfolket: «Herren vere med dykk!» Dei svara honom: «Herren velsigne deg!»',
        5: 'Og Boaz spurde den drengen som hadde tilsyn med skurdfolket: «Kven høyrer ho til denne unge kvinna?»',
        6: 'Drengen som hadde tilsyn med skurdfolket, svara og sagde: «Det er ei moabitkvinna, ho som fylgde med No’omi hit frå Moablandet.',
        7: 'Ho spurde um ho kunde få plukka og henta i hop aks millom kornbandi etter skurdfolket, og so kom ho, og hev halde på sidan i dag tidleg alt til no og ikkje kvilt det slag.»',
        8: 'Då sagde Boaz til Rut: «Høyr, dotter mi! Du skal ikkje ganga stad og plukka aks på nokon annan åker; gakk ikkje her ifrå heller, men haldt deg åt tenestgjentorne mine her!',
        9: 'Ansa etter kvar skurdfolket arbeider på åkeren, og gakk etter deim! Eg hev sagt åt drengjerne at dei ikkje skal gjera deg noko vondt. Og um du vert tyrst, so gakk burt åt kjeri og drikk av det vatnet drengjerne hentar!»',
        10: 'Då kasta ho seg ned med andlitet mot jordi og sagde til honom: «Kvifor hev eg funne slik nåde for augo dine, at du tek deg av meg som er framand?»',
        11: 'Boaz svara og sagde til henne: «Dei hev fortalt meg kva du hev gjort mot vermor di, etterat mannen din var avliden, korleis du hev forlate far din og mor di og fedrelandet ditt og fare til eit folk som du fyrr ikkje kjende.',
        12: 'Herren løne deg for det du hev gjort, ja måtte du få fullt vederlag av Herren, Israels Gud, han som du hev kome til, for å finna livd under vengjerne hans!»',
        13: 'Ho sagde: «So må eg då finna nåde for augo dine, herre; etter di du hev trøysta meg og tala venleg med tenestgjenta di, endå eg ikkje ein gong er so mykje som ei av tenestgjentorne dine.»',
        14: 'Då det leid til måls, sagde Boaz til henne: «Kom hit og et av brødet, og stikk brødstykket ditt ned i vinen!» Då sette ho seg attmed skurdfolket, og han lagde fram åt henne brunsteikte aks, og ho åt og vart mett, og hadde endå att.',
        15: 'Då ho stod upp og skulde plukka aks, sagde Boaz til drengjerne sine: «Lat henne og plukka aks millom kornbandi, og gjer henne ikkje noko til mein!',
        16: 'Ja, de kann gjerne draga ut strå or bandi og lata deim liggja, so ho fær plukka deim upp, og ingen skal vera vond på henne for det.»',
        17: 'So plukka ho aks på åkeren alt til kvelds. Og då ho banka or det ho hadde plukka, vart det på lag ein skjeppa bygg.',
        18: 'Og ho tok byrdi si og gjekk inn i byen, og vermor hennar fekk sjå kva ho hadde plukka. So tok ho fram og gav henne det som vart att då ho hadde ete seg mett.',
        19: 'Då sagde vermor hennar til henne: «Kvar hev du plukka aks i dag, og kvar hev du arbeidt? Velsigna vere han som hev hjelpt deg til det!» So fortalde ho vermor si kven ho hadde arbeidt hjå, og sagde: «Den mannen som eg hev arbeidt hjå i dag, heiter Boaz.»',
        20: 'Då sagde No’omi til sonekona si: «Herren velsigne honom, for di han gjer miskunn både mot deim som liver og dei avlidne!» Og No’omi sagde til henne: «Denne mannen er av frendarne våre, ein av løysingsmennerne våre.»',
        21: 'Moabitkvinna Rut sagde: «Han sagde og til meg: Haldt deg åt drengjerne mine til dei hev gjort frå seg all skurden min!»',
        22: 'Då sagde No’omi til Rut, sonekona si: «Ja, det er best, dotter mi, at du gjeng med tenestgjentorne hans; so dei ikkje skal gjera deg noko vondt på ein annan åker.»',
        23: 'So heldt ho seg åt tenestgjentorne hans Boaz og plukka aks der til dei vart ferdige både med bygg- og kveiteskurden. Men ho budde hjå vermor si.',
    },
    3: {
        1: 'Og No’omi, vermor hennar, sagde til henne: «Dotter mi, eg vil sjå til å hjelpa deg, so du kann finna ein kvilestad, der du kann få det godt.',
        2: 'Høyr no: Boaz, som du hev vore saman med tenestgjentorne åt, han er frenden vår. No i natt kastar han bygg på treskjestaden sin.',
        3: 'Vaska deg no og salva deg; klæd so på deg og gakk ned på plassen. Men lat honom ikkje sjå deg fyrr han hev ete og drukke.',
        4: 'Når han legg seg, sjå so etter kvar han legg seg. Gakk dit og lyft upp klædet nedmed føterne hans, og legg deg der! då vil han segja deg sjølv kva du skal gjera!»',
        5: 'Ho svara henne: «Alt det du segjer, vil eg gjera.»',
        6: 'Og ho gjekk ho ned på treskjarplassen og gjorde alt so som vermor hennar hadde sagt ho skulle gjera.',
        7: 'Då Boaz hadde ete og drukke, var han i godlag og lagde seg attmed kornhaugen; då gjekk ho stilt dit og lyfte upp klædet nedmed føterne hans, og lagde seg der.',
        8: 'Ved midnattsleite vart mannen uppskræmd og bøygde seg framyver, og so fekk han sjå at det låg ei kvinna nedmed føterne hans.',
        9: '«Kven er du?» sagde han. Ho svara: «Eg er Rut, trælkvinna di; breid ut vengjerne dine yver trælkvinna di, for du er løysingsmannen min.»',
        10: 'Då sagde han: «Herren velsigne deg, dotter mi! Du hev no synt større kjærleik enn fyrr, for du hev ikkje rent etter unge menner, korkje fatige eller rike.',
        11: 'Ver no ikkje rædd, dotter mi! Alt det du segjer, vil eg gjera; for alt folket i byen veit at du er ei dygdefull kvinna.',
        12: 'Det er no sant og visst at eg er løysingsmannen din; men det er ein annan løysingsmann som er næmare enn eg.',
        13: 'Ver no her i natt; vil han då i morgon løysa deg, so lat honom gjera det; men hev han ikkje hug til å løysa deg, so skal eg gjera det, so sant Herren liver! Ligg no her til morgons!»',
        14: 'So låg ho då nedmed føterne hans til morgons; men ho stod upp fyrr den eine kunde skilja den andre greidt; for han tenkte: «Det må ikkje nokon vita at kvinna hev kome hit til treskjarplassen.',
        15: 'Og han sagde: Kom med kåpa du hev på deg, og haldt henne fram!» Og ho hene fram. Då mælte han i seks mål bygg og gav henne; dermed gjekk ho inn i byen.',
        16: 'Og då ho kom til vermor si, sagde ho: «Korleis hev det gjenge, dotter mi?» Då fortalde ho henne alt det mannen hadde gjort mot henne.',
        17: 'Og ho sagde: «Desse seks måli med bygg gav han meg og sagde: «Du skal ikkje koma tomhendt heim til vermor di.»»',
        18: 'Då svara ho: «Haldt deg no roleg, dotter mi, til du fær sjå korleis det gjeng! for den mannen gjev seg ikkje fyrr han fær avgjort saki i dag.»',
    },
    4: {
        1: 'Og Boaz hadde gjenge upp på tinget og sett seg der. Då høvde det so at den løysingsmannen som Boaz hadde tala um, gjekk framum der. Han tala åt honom og sagde: «Kom hit og set deg her!» Og han kom og sette seg.',
        2: 'So tok han burtåt seg ti av styresmennerne i byen og sagde: «Set dykk her!» Og dei sette seg.',
        3: 'Då sagde han til løysingsmannen: «Det åkerstykket som høyrde Elimelek, bror vår, til, vil No’omi selja, ho som hev kome att frå Moablandet.',
        4: 'Difor tenkte eg at eg skulde fortelja deg det og segja: Kjøp det du når dei er til stades dei som sit her, og styresmennerne for folket mitt! Vil du taka det etter løysingsretten, so gjer det; vil du ikkje løysa det, då seg meg det, so eg fær vita det; for ingen annan eig løysingsretten enn du, og næst etter deg er det eg sjølv.» Han sagde: «Eg vil løysa det.»',
        5: 'Då sagde Boaz: «Når du kjøper åkeren av No’omi, so kjøper du honom og av moabitkvinna Rut, kona åt den avlidne, og du skyldar å reisa upp att namnet åt den avlidne, og festa det til arvluten hans.»',
        6: 'Løysingsmannen svara: «Då kann eg ikkje nytta løysingsretten min, for so spiller eg min eigen arvlut. Løys du åt deg det eg skulde ha løyst, for eg kann ikkje gjera det.»',
        7: 'Det var gamall sed i Israel når ein mann skulde stadfesta ei løysing eller eit avtala byte, då drog han av seg skoen og gav honom til den andre, og dette gjaldt som ein vitnesburd i Israel.',
        8: 'Då sagde løysingsmannen til Boaz: «Kjøp det du!» og so drog han av seg skoen.',
        9: 'Boaz sagde no til styresmennerne og til alt folket: «De er i dag vitne på at eg hev kjøpt av No’omi alt det som hev høyrt Elimelek til, og alt som hev høyrt Kiljon og Mahlon til.',
        10: 'Like eins hev eg kjøpt moabitkvinna Rut, kona hans Mahlon, til kona åt meg, so eg kann reisa namnet åt den avlidne og festa det til arvluten hans, so namnet hans ikkje kjem burt millom brørne hans eller frå porten på heimstaden hans. De er vitne på dette i dag.»',
        11: 'Og alt folket som var på tinget og styresmennerne sagde: «Ja, det er me. Herren gjeve at den kvinna som no gjeng inn i huset ditt, må verta som Rakel og Lea, dei tvo som hev bygt upp Israels hus! Og gjev du må koma til velmagt i Efrata og verta namngjeten i Betlehem!',
        12: 'Og gjev at dei etterkomarar som Herren vil gjeva deg med denne unge kvinna, må verta ei ætt som ætti hans Peres, han som Tamar fødde åt Juda!»',
        13: 'So tok då Boaz Rut til seg, og ho vart kona hans; han gjekk inn til henne, og Herren gav henne livsfrukt, og ho fødde ein son.',
        14: 'Då sagde kvinnorne til No’omi: «Lova vere Herren som hev gjort at du idag ikkje vantar løysingsmann! Han skal verta namngjeten i Israel.',
        15: 'Han skal verta ein trøystar åt deg og din alderdoms hjelp; for sonekona di, ho som held av deg, hev født honom; ho som er meir for deg enn sju søner.»',
        16: 'Og No’omi tok barnet og lagde det i fanget sitt og vart fostermor åt det.',
        17: 'Og grannekvinnorne gav honom namn og sagde: «No’omi hev fenge ein son,» og dei gav honom namnet Obed; Han vart far åt Isai, far åt David.',
        18: 'Her er ættartalet hans Peres: Peres var far åt Hesron.',
        19: 'Hesron var far åt Ram, og Ram var far åt Amminadab.',
        20: 'Amminadab var far åt Nahson, og Nahson far åt Salma.',
        21: 'Salmon var far åt Boaz, og Boaz far åt Obed.',
        22: 'Obed var far åt Isai, og Isai far åt David.',
    },
}
